def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    if not archive:
        raise ValueError("Archive is empty.")

    # Select the solution with the highest potential (product of objectives)
    potentials = [obj[0] * obj[1] for _, obj in archive]
    selected_idx = np.argmax(potentials)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst[base_solution == 1])

    # Generate a neighbor solution using hybrid local search
    new_solution = base_solution.copy()
    n_items = len(weight_lst)

    # Strategy 1: Randomly swap two items (if feasible)
    if n_items >= 2:
        swap_indices = np.random.choice(n_items, 2, replace=False)
        if new_solution[swap_indices[0]] != new_solution[swap_indices[1]]:
            # Check feasibility
            if new_solution[swap_indices[0]] == 1:
                new_weight = current_weight - weight_lst[swap_indices[0]] + weight_lst[swap_indices[1]]
            else:
                new_weight = current_weight + weight_lst[swap_indices[0]] - weight_lst[swap_indices[1]]
            if new_weight <= capacity:
                new_solution[swap_indices[0]], new_solution[swap_indices[1]] = new_solution[swap_indices[1]], new_solution[swap_indices[0]]

    # Strategy 2: Probabilistic flip of items with low marginal contribution
    for i in range(n_items):
        if np.random.rand() < 0.2:  # 20% chance to flip
            if new_solution[i] == 1:
                new_weight = current_weight - weight_lst[i]
                if new_weight >= 0:  # Ensure non-negative weight (though capacity check is more important)
                    new_solution[i] = 0
            else:
                new_weight = current_weight + weight_lst[i]
                if new_weight <= capacity:
                    new_solution[i] = 1

    # Ensure feasibility (in case of multiple changes)
    total_weight = np.sum(weight_lst[new_solution == 1])
    if total_weight > capacity:
        # Remove items until feasible
        excess = total_weight - capacity
        while excess > 0:
            included_items = np.where(new_solution == 1)[0]
            if len(included_items) == 0:
                break
            remove_idx = np.random.choice(included_items)
            excess -= weight_lst[remove_idx]
            new_solution[remove_idx] = 0

    return new_solution

def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    if not archive:
        return np.zeros_like(weight_lst, dtype=int)

    # Select a solution with high potential for improvement (diversity-aware)
    selected_idx = random.choices(range(len(archive)), weights=[1/(1 + i) for i in range(len(archive))])[0]
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Calculate current weight and combined value ratios
    current_weight = np.sum(weight_lst[base_solution == 1])
    combined_ratios = (value1_lst + value2_lst) / weight_lst

    # Hybrid local search: probabilistic greedy insertion (70%) and value-aware replacement (30%)
    if random.random() < 0.7:
        # Probabilistic greedy insertion: add high-value items not in solution
        not_in_solution = np.where(base_solution == 0)[0]
        if len(not_in_solution) > 0:
            # Select top 30% items by combined ratio
            top_candidates = not_in_solution[np.argsort(combined_ratios[not_in_solution])[-max(1, len(not_in_solution)//3):]]
            if len(top_candidates) > 0:
                insert_idx = random.choice(top_candidates)
                if current_weight + weight_lst[insert_idx] <= capacity:
                    new_solution[insert_idx] = 1
    else:
        # Value-aware replacement: swap low-value items with high-value items
        in_solution = np.where(base_solution == 1)[0]
        if len(in_solution) > 0:
            # Find low-value items (bottom 40%)
            low_value_items = in_solution[np.argsort(combined_ratios[in_solution])[:max(1, len(in_solution)//2)]]
            if len(low_value_items) > 0:
                replace_out = random.choice(low_value_items)
                not_in_solution = np.where(base_solution == 0)[0]
                if len(not_in_solution) > 0:
                    # Find high-value items (top 40%)
                    high_value_items = not_in_solution[np.argsort(combined_ratios[not_in_solution])[-max(1, len(not_in_solution)//2):]]
                    if len(high_value_items) > 0:
                        replace_in = random.choice(high_value_items)
                        if (current_weight - weight_lst[replace_out] + weight_lst[replace_in]) <= capacity:
                            new_solution[replace_out] = 0
                            new_solution[replace_in] = 1

    # Dynamic marginal contribution flip (25% chance for each item)
    for i in range(len(weight_lst)):
        if random.random() < 0.25:
            if new_solution[i] == 1:
                # Calculate marginal contribution
                marginal = (value1_lst[i] + value2_lst[i]) / weight_lst[i]
                threshold = np.mean(combined_ratios[new_solution == 1]) if np.sum(new_solution) > 0 else 0
                if marginal < threshold:
                    new_solution[i] = 0
            else:
                if (current_weight + weight_lst[i]) <= capacity:
                    new_solution[i] = 1

    # Ensure feasibility by removing low-value items if weight exceeds capacity
    total_weight = np.sum(weight_lst[new_solution == 1])
    if total_weight > capacity:
        excess = total_weight - capacity
        while excess > 0 and np.sum(new_solution) > 0:
            included_items = np.where(new_solution == 1)[0]
            remove_idx = included_items[np.argmin((value1_lst + value2_lst)[included_items] / weight_lst[included_items])]
            excess -= weight_lst[remove_idx]
            new_solution[remove_idx] = 0

    return new_solution
